/**
 * A catalog course. Subject + number is meant to be the "human" identity
 * of a course (e.g. "INTEGBI 130"), but this record is fed by an upstream
 * source-of-record system that renumbers courses on its own schedule. When
 * a course is renumbered, THIS record can lag behind reality for a while:
 * it keeps reporting the old number until a separate "future" version of
 * the course is promoted into it.
 */
export interface Course {
  courseId: string;
  subject: string;
  number: string;
  title: string;
}

/**
 * A specific offering of a course in a given term (what students actually
 * enroll in). `subject` / `courseNumber` here are the CURRENT, correct
 * identity of the course this offering belongs to -- they are populated
 * from the same upstream feed as `Course`, but on the offering itself they
 * are always up to date. `number` is unrelated: it's the section number
 * (e.g. "001"), not the course number.
 */
export interface ClassOffering {
  classId: string;
  courseId: string;
  subject: string;
  courseNumber: string;
  number: string; // section number, e.g. "001" -- NOT a course number
  sessionId: string;
  title?: string;
}

/** An admin-curated "featured class" entry, as saved by the curation tool. */
export interface CuratedClass {
  _id: string;
  classId: string;
  subject: string;
  courseNumber: string;
  sectionNumber: string;
  sessionId: string;
  text: string;
  createdAt: string;
}

/** An entry in the picker an admin uses to choose which class to curate. */
export interface CatalogEntry {
  classId: string;
  subject: string;
  courseNumber: string;
  sectionNumber: string;
  sessionId: string;
  title: string;
}
